/**
 * FROZEN — deck-v1
 *
 * This file is an immutable snapshot of the deck derivation used by
 * packages/poker-engine/src/deck.ts when a hand is dealt.
 *
 * DO NOT EDIT THIS FILE. Any change to the derivation invalidates every
 * commitment ever published and makes past hands unverifiable.
 * To change the derivation, add fair/deck-v2.ts (and a new algorithm id).
 *
 * deck-v1 derivation:
 *   1. deck = suits x ranks, suits in order s,h,d,c, ranks in order A..2
 *   2. hash the seed string with the Java-style int hash
 *      h = (h << 5) - h + charCode, coerced to int32 after every char
 *   3. xorshift32 PRNG seeded with (h || 1)
 *   4. Fisher-Yates from the end, rng() = ((state >>> 0) % 100000) / 100000
 */

import crypto from 'crypto';

export interface FairCard {
  r: string;
  s: string;
}

export const DECK_V1_ALGORITHM = 'deck-v1';

export const DECK_V1_SUITS = ['s', 'h', 'd', 'c'];
export const DECK_V1_RANKS = ['A', 'K', 'Q', 'J', 'T', '9', '8', '7', '6', '5', '4', '3', '2'];

export function makeDeckV1(): FairCard[] {
  const deck: FairCard[] = [];
  for (const s of DECK_V1_SUITS) {
    for (const r of DECK_V1_RANKS) {
      deck.push({ r, s });
    }
  }
  return deck;
}

export function shuffleDeckV1(deck: FairCard[], seed: string): FairCard[] {
  if (!seed || typeof seed !== 'string' || seed.length === 0) {
    throw new Error('deck-v1 requires a non-empty seed');
  }

  let h = 0;
  for (let i = 0; i < seed.length; i++) {
    h = (h << 5) - h + seed.charCodeAt(i);
    h |= 0;
  }
  let state = h || 1;
  const rng = (): number => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    state |= 0;
    return ((state >>> 0) % 100000) / 100000;
  };

  const arr = deck.slice();
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }

  return arr;
}

export function deckFromSeedV1(serverSeed: string): FairCard[] {
  return shuffleDeckV1(makeDeckV1(), serverSeed);
}

export function cardKey(card: FairCard): string {
  return `${card.r}${card.s}`;
}

/** Canonical, order-sensitive serialization of a deck. */
export function deckStringV1(cards: FairCard[]): string {
  return cards.map(cardKey).join(',');
}

export function deckHashV1(cards: FairCard[]): string {
  return sha256Hex(deckStringV1(cards));
}

export function sha256Hex(input: string): string {
  return crypto.createHash('sha256').update(input).digest('hex');
}
